BEGIN READ ONLY; SELECT jsonb_object_agg(table_name,rows) AS record_counts FROM (SELECT 'public.reference_values'::text AS table_name,count(*) AS rows FROM public.reference_values UNION ALL SELECT 'public.children'::text AS table_name,count(*) AS rows FROM public.children UNION ALL SELECT 'gk_private.child_private_profiles'::text AS table_name,count(*) AS rows FROM gk_private.child_private_profiles UNION ALL SELECT 'gk_private.caregivers'::text AS table_name,count(*) AS rows FROM gk_private.caregivers UNION ALL SELECT 'public.child_caregivers'::text AS table_name,count(*) AS rows FROM public.child_caregivers UNION ALL SELECT 'public.program_changes'::text AS table_name,count(*) AS rows FROM public.program_changes UNION ALL SELECT 'public.questionnaire_responses'::text AS table_name,count(*) AS rows FROM public.questionnaire_responses UNION ALL SELECT 'public.questionnaire_items'::text AS table_name,count(*) AS rows FROM public.questionnaire_items UNION ALL SELECT 'gk_private.questionnaire_answers'::text AS table_name,count(*) AS rows FROM gk_private.questionnaire_answers UNION ALL SELECT 'public.attendance_observations'::text AS table_name,count(*) AS rows FROM public.attendance_observations UNION ALL SELECT 'public.support_observations'::text AS table_name,count(*) AS rows FROM public.support_observations UNION ALL SELECT 'public.adl_visits'::text AS table_name,count(*) AS rows FROM public.adl_visits UNION ALL SELECT 'gk_private.source_artifacts'::text AS table_name,count(*) AS rows FROM gk_private.source_artifacts UNION ALL SELECT 'gk_private.source_records'::text AS table_name,count(*) AS rows FROM gk_private.source_records UNION ALL SELECT 'gk_private.source_provenance'::text AS table_name,count(*) AS rows FROM gk_private.source_provenance UNION ALL SELECT 'gk_private.access_memberships'::text AS table_name,count(*) AS rows FROM gk_private.access_memberships UNION ALL SELECT 'gk_private.identity_candidates'::text AS table_name,count(*) AS rows FROM gk_private.identity_candidates UNION ALL SELECT 'gk_private.recovery_actions'::text AS table_name,count(*) AS rows FROM gk_private.recovery_actions UNION ALL SELECT 'gk_private.record_audit_events'::text AS table_name,count(*) AS rows FROM gk_private.record_audit_events) counts; ROLLBACK;
